import React, { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { Helmet } from 'react-helmet';
import Header from '../../components/ui/Header';
import Footer from '../../components/ui/Footer';
import Icon from '../../components/AppIcon';
import Button from '../../components/ui/Button';
import { supabaseService } from '../../services/supabaseService';
import { useToast } from '../../contexts/ToastContext';
import Modal from '../../components/ui/Modal';
import { cn } from '../../utils/cn';
import LiveSessionBanner from '../../components/academy/LiveSessionBanner';
import AuthRequiredModal from '../../components/ui/AuthRequiredModal';

const BrainstormSessions = () => {
    const navigate = useNavigate();
    const { addToast } = useToast();
    const { user } = useSelector(state => state.auth);
    const [sessions, setSessions] = useState([]);
    const [loading, setLoading] = useState(true);
    const [profile, setProfile] = useState(null);
    const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
    const [isStartNowModalOpen, setIsStartNowModalOpen] = useState(false);
    const [startNowTitle, setStartNowTitle] = useState('');
    const [lobbyMembers, setLobbyMembers] = useState([]); // List of profile objects
    const [memberSearch, setMemberSearch] = useState('');
    const [searchResults, setSearchResults] = useState([]);
    const [onlineUsers, setOnlineUsers] = useState([]);
    const [isSearching, setIsSearching] = useState(false);
    const [isSearchFocused, setIsSearchFocused] = useState(false);
    const [isCreating, setIsCreating] = useState(false);
    const [editingSession, setEditingSession] = useState(null);
    const [sessionToDelete, setSessionToDelete] = useState(null);
    const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
    const [scheduleData, setScheduleData] = useState({
        title: '',
        date: '',
        time: ''
    });

    // Fetch latest profile data to ensure we have the full name
    useEffect(() => {
        const fetchLatestProfile = async () => {
            if (user?.id) {
                try {
                    const data = await supabaseService.getProfile(user.id);
                    setProfile(data);
                } catch (err) {
                    console.error("Error fetching profile:", err);
                }
            }
        };
        fetchLatestProfile();
    }, [user?.id]);

    useEffect(() => {
        fetchSessions();
        const subscription = supabaseService.supabase
            .channel('live_sessions_updates')
            .on('postgres_changes', { event: '*', table: 'live_sessions' }, fetchSessions)
            .subscribe();

        return () => subscription.unsubscribe();
    }, []);

    const fetchSessions = async () => {
        try {
            let query = supabaseService.supabase
                .from('live_sessions')
                .select('*, host:profiles(full_name, avatar_url)')
                .not('title', 'ilike', 'Assignment:%')
                .not('title', 'ilike', 'Assessment:%')
                .not('title', 'ilike', 'Attendance:%')
                .order('start_time', { ascending: true });

            if (user?.id) {
                // Show sessions that are:
                // 1. Live or Waiting (Public)
                // 2. Pending and hosted by me
                // 3. Pending and I am an invited member (stored in metadata)
                query = query.or(`status.in.(live,waiting),and(status.eq.pending,host_id.eq.${user.id}),and(status.eq.pending,metadata->invited_member_ids.cs.["${user.id}"])`);
            } else {
                query = query.in('status', ['live', 'waiting']);
            }

            const { data, error } = await query;
            if (error) throw error;
            setSessions(data || []);
        } catch (err) {
            console.error("Failed to fetch sessions", err);
        } finally {
            setLoading(false);
        }
    };

    // Handle User Search for Lobby
    useEffect(() => {
        const fetchOnline = async () => {
            try {
                const results = await supabaseService.getOnlineUsers();
                setOnlineUsers(results.filter(r => 
                    r.id !== user?.id && !lobbyMembers.find(m => m.id === r.id)
                ));
            } catch (err) {
                console.error("Online users error:", err);
            }
        };

        if (isStartNowModalOpen || isScheduleModalOpen) {
            fetchOnline();
        }
    }, [isStartNowModalOpen, isScheduleModalOpen, lobbyMembers, user?.id]);

    useEffect(() => {
        const delayDebounceFn = setTimeout(async () => {
            if (memberSearch.trim().length >= 2) {
                setIsSearching(true);
                try {
                    const results = await supabaseService.searchUsers(memberSearch);
                    // Filter out already added members and the current user
                    setSearchResults(results.filter(r => 
                        r.id !== user.id && !lobbyMembers.find(m => m.id === r.id)
                    ));
                } catch (err) {
                    console.error("Search error:", err);
                } finally {
                    setIsSearching(false);
                }
            } else {
                setSearchResults([]);
            }
        }, 300);

        return () => clearTimeout(delayDebounceFn);
    }, [memberSearch, lobbyMembers, user?.id]);

    const handleAddLobbyMember = (member) => {
        setLobbyMembers(prev => [...prev, member]);
        setMemberSearch('');
        setSearchResults([]);

        // Broadcast invitation to the tagged user
        if (user && member.id !== user.id) {
            supabaseService.supabase.channel('platform_notifications').send({
                type: 'broadcast',
                event: 'LOBBY_INVITE',
                payload: {
                    targetUserId: member.id,
                    hostName: profile?.full_name || user?.user_metadata?.full_name || user?.email?.split('@')[0],
                    title: startNowTitle || scheduleData.title || "a brainstorm session",
                    isScheduled: isScheduleModalOpen
                }
            });
        }
    };

    const handleRemoveLobbyMember = (id) => {
        setLobbyMembers(prev => prev.filter(m => m.id !== id));
    };

    const handleCreateNow = () => {
        if (!user) {
            setIsAuthModalOpen(true);
            return;
        }
        const hostName = profile?.full_name || user?.user_metadata?.full_name || user?.email?.split('@')[0] || 'Member';
        setStartNowTitle(`${hostName}'s Brainstorm`);
        setLobbyMembers([profile || { id: user.id, full_name: user.user_metadata?.full_name || user.email.split('@')[0] }]);
        setIsStartNowModalOpen(true);
    };

    const handleScheduleClick = () => {
        if (!user) {
            setIsAuthModalOpen(true);
            return;
        }
        setEditingSession(null);
        setScheduleData({ title: '', date: '', time: '' });
        setLobbyMembers([profile || { id: user.id, full_name: user.user_metadata?.full_name || user.email.split('@')[0] }]);
        setIsScheduleModalOpen(true);
    };

    const confirmCreateNow = async (e) => {
        e.preventDefault();
        if (!user) return;
        setIsCreating(true);
        try {
            const hostName = profile?.full_name || user?.user_metadata?.full_name || user?.email?.split('@')[0] || 'Member';
            const newSession = await supabaseService.createLiveSession({
                title: startNowTitle || `${hostName}'s Brainstorm`,
                session_type: 'collaboration',
                status: 'pending',
                start_time: new Date().toISOString(),
                is_public: true,
                metadata: {
                    invited_member_ids: lobbyMembers.map(m => m.id).filter(id => id !== user.id)
                }
            });

            setIsStartNowModalOpen(false);
            addToast('Brainstorm room created! Waiting for Approval.', 'success');
        } catch (err) {
            addToast('Failed to start session', 'error');
        } finally {
            setIsCreating(false);
        }
    };

    const handleScheduleSession = async (e) => {
        e.preventDefault();
        if (!user || lobbyMembers.length < 2) return;
        setIsCreating(true);
        try {
            const startTime = new Date(`${scheduleData.date}T${scheduleData.time}`);
            if (startTime < new Date()) {
                addToast('Please pick a future date and time', 'warning');
                return;
            }

            const hostName = profile?.full_name || user?.user_metadata?.full_name || user?.email?.split('@')[0] || 'Member';
            
            const sessionPayload = {
                title: scheduleData.title || `${hostName}'s Scheduled Brainstorm`,
                session_type: 'collaboration',
                status: 'pending',
                start_time: startTime.toISOString(),
                is_public: true,
                metadata: {
                    invited_member_ids: lobbyMembers.map(m => m.id).filter(id => id !== user.id)
                }
            };

            if (editingSession) {
                await supabaseService.updateLiveSession(editingSession.id, sessionPayload);
                addToast('Session updated successfully!', 'success');
            } else {
                await supabaseService.createLiveSession(sessionPayload);
                addToast('Session scheduled and submitted for Approval!', 'success');
            }

            setIsScheduleModalOpen(false);
            setEditingSession(null);
            setScheduleData({ title: '', date: '', time: '' });
            setLobbyMembers([]);
            fetchSessions();
        } catch (err) {
            addToast(`Failed to ${editingSession ? 'update' : 'schedule'} session`, 'error');
        } finally {
            setIsCreating(false);
        }
    };

    const handleEditClick = (session) => {
        const dateObj = new Date(session.start_time);
        setEditingSession(session);
        setScheduleData({
            title: session.title,
            date: dateObj.toISOString().split('T')[0],
            time: dateObj.toTimeString().slice(0, 5)
        });
        setIsScheduleModalOpen(true);
    };

    const handleDeleteSession = (session) => {
        setSessionToDelete(session);
    };

    const confirmDelete = async () => {
        if (!sessionToDelete) return;
        
        const targetId = sessionToDelete.id;
        setIsCreating(true);
        try {
            // "Soft Delete" approach: Update status to cancelled instead of hard deleting
            // This is safer and usually bypasses restrictive DELETE RLS policies
            await supabaseService.updateLiveSessionStatus(targetId, 'cancelled');
            
            // Optimistic UI Update: Remove from local state immediately
            setSessions(prev => prev.filter(s => s.id !== targetId));
            
            addToast('Session cancelled', 'success');
            setSessionToDelete(null);
            
            // Also trigger a background fetch to ensure sync
            fetchSessions();
        } catch (err) {
            console.error("Cancellation Error:", err);
            addToast('Failed to cancel session. Please try again.', 'error');
            fetchSessions(); // Refresh to restore the session in the UI
        } finally {
            setIsCreating(false);
        }
    };

    const handleStartScheduledSession = async (session) => {
        setIsCreating(true);
        try {
            await supabaseService.updateLiveSessionStatus(session.id, 'live');
            
            // Broadcast to platform for instant alerts
            const hostName = profile?.full_name || user?.user_metadata?.full_name || user?.email?.split('@')[0] || 'Member';
            supabaseService.supabase.channel('platform_notifications').send({
                type: 'broadcast',
                event: 'NEW_LIVE_SESSION',
                payload: { hostName, title: session.title, sessionId: session.id }
            });

            addToast('Session is now LIVE!', 'success');
            navigate(`/academy/live/${session.meeting_id}`);
        } catch (err) {
            addToast('Failed to start session', 'error');
        } finally {
            setIsCreating(false);
        }
    };

    const liveSessions = sessions.filter(s => s.status === 'live');
    const scheduledSessions = sessions.filter(s => s.status === 'waiting');
    const pendingSessions = sessions.filter(s => s.status === 'pending');

    return (
        <div className="min-h-screen bg-[#0A0C10] text-white">
            <Helmet>
                <title>Brainstorm Hub | LUC Academy</title>
                <meta name="description" content="Collaborate in real-time with other students and mentors." />
            </Helmet>

            <Header />

            <main className="pt-24 pb-20 px-4 sm:px-6 lg:px-8 max-w-7xl mx-auto">
                <button 
                    onClick={() => navigate('/academy')}
                    className="flex items-center gap-2 text-slate-400 hover:text-white transition-colors mb-8 group"
                >
                    <Icon name="ArrowLeft" size={18} className="group-hover:-translate-x-1 transition-transform" />
                    <span className="text-sm font-bold uppercase tracking-widest">Back to Academy</span>
                </button>

                {/* Hero Section */}
                <div className="relative rounded-[3rem] overflow-hidden bg-gradient-to-br from-brand-blue/20 to-purple-600/20 border border-white/10 p-8 md:p-16 mb-12">
                    <div className="relative z-10 max-w-2xl">
                        <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-white/5 border border-white/10 mb-6">
                            <div className="w-2 h-2 bg-brand-blue rounded-full animate-pulse" />
                            <span className="text-[10px] font-black tracking-[0.2em] text-brand-blue uppercase">Collaboration Hub</span>
                        </div>
                        <h1 className="text-4xl md:text-6xl font-black italic tracking-tighter mb-6 leading-[0.9]">
                            WHERE <span className="text-brand-blue">BIG IDEAS</span> COLLIDE.
                        </h1>
                        <p className="text-slate-400 text-lg font-medium mb-8">
                            Don't study in isolation. Start a live room, share your screen, and brainstorm your next big move with the LUC community.
                        </p>

                        {!user && (
                            <div className="mb-8 p-4 rounded-2xl bg-brand-blue/10 border border-brand-blue/20 flex items-start gap-3 animate-in slide-in-from-left duration-500">
                                <Icon name="Info" className="text-brand-blue mt-0.5 shrink-0" size={18} />
                                <div>
                                    <p className="text-sm font-bold text-white mb-1 tracking-tight">MEMBERS ONLY HUB</p>
                                    <p className="text-xs text-slate-400 leading-relaxed">
                                        Login or Create an Account to start your own rooms, schedule future brainstorms, and receive reminders for upcoming sessions.
                                    </p>
                                </div>
                            </div>
                        )}

                        <div className="flex flex-wrap gap-4">
                            <Button onClick={handleCreateNow} className="font-black italic px-8">START NOW</Button>
                            <Button variant="secondary" onClick={handleScheduleClick} className="font-black italic px-8">SCHEDULE FOR LATER</Button>
                        </div>
                    </div>
                    {/* Abstract background shapes */}
                    <div className="absolute top-0 right-0 w-1/2 h-full opacity-20 pointer-events-none">
                        <div className="absolute top-1/4 right-1/4 w-64 h-64 bg-brand-blue rounded-full blur-[120px]" />
                        <div className="absolute bottom-1/4 right-1/3 w-48 h-48 bg-purple-500 rounded-full blur-[100px]" />
                    </div>
                </div>

                {/* Pending Approval Section (Only visible to the creator) */}
                {pendingSessions.length > 0 && (
                    <div className="mb-12 animate-in fade-in slide-in-from-top duration-700">
                        <div className="flex items-center gap-3 mb-6">
                            <div className="flex items-center justify-center w-10 h-10 rounded-xl bg-indigo-500/10 border border-indigo-500/20">
                                <Icon name="Clock" className="text-indigo-400" size={20} />
                            </div>
                            <div>
                                <h2 className="text-2xl font-black italic tracking-tight text-indigo-400 leading-tight">AWAITING APPROVAL</h2>
                                <p className="text-[10px] font-bold text-indigo-500/50 uppercase tracking-widest">Only visible to you until approved</p>
                            </div>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                            {pendingSessions.map(session => (
                                <div key={session.id} className="relative group bg-indigo-500/5 border border-indigo-500/10 rounded-[2.5rem] p-8 overflow-hidden hover:bg-indigo-500/10 transition-all duration-500">
                                    <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-500/10 blur-[50px] -mr-16 -mt-16" />
                                    
                                    <div className="flex justify-between items-start mb-4">
                                        <div className="flex flex-col gap-1 pr-4">
                                            <h3 className="text-xl font-bold line-clamp-1">{session.title}</h3>
                                            {session.host_id !== user?.id && (
                                                <span className="text-[10px] font-black text-brand-blue uppercase tracking-widest flex items-center gap-1">
                                                    <Icon name="Users" size={10} /> You're a Partner
                                                </span>
                                            )}
                                        </div>
                                        <div className="flex items-center gap-1.5 px-3 py-1 rounded-full bg-indigo-500/20 border border-indigo-500/30">
                                            <div className="w-1.5 h-1.5 bg-indigo-400 rounded-full animate-pulse" />
                                            <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Reviewing</span>
                                        </div>
                                    </div>

                                    <p className="text-slate-400 text-sm mb-6 italic leading-relaxed">
                                        Submitted and awaiting approval. It will appear live shortly!
                                    </p>
                                    
                                    <div className="flex items-center gap-3 pt-6 border-t border-indigo-500/10">
                                        <div className="w-8 h-8 rounded-full border border-indigo-500/20 bg-indigo-500/10 flex items-center justify-center overflow-hidden">
                                            <img 
                                                src={session.host?.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(session.host?.full_name || 'H')}`}
                                                className="w-full h-full object-cover"
                                                alt="Host"
                                            />
                                        </div>
                                        <div>
                                            <p className="text-xs font-bold text-indigo-300">{session.host?.full_name}</p>
                                            <p className="text-[9px] text-indigo-300/40 uppercase font-black tracking-widest">Creator</p>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
                    {/* Live Now Column */}
                    <div className="lg:col-span-2">
                        <div className="flex items-center justify-between mb-6">
                            <div className="flex items-center gap-3">
                                <Icon name="Zap" className="text-brand-blue" />
                                <h2 className="text-2xl font-black italic tracking-tight">LIVE NOW</h2>
                            </div>
                            <span className="px-3 py-1 rounded-lg bg-brand-blue/10 text-brand-blue text-[10px] font-bold">
                                {liveSessions.length} ROOMS ACTIVE
                            </span>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            {liveSessions.length > 0 ? liveSessions.map(session => (
                                <div key={session.id} className="group bg-white/5 border border-white/5 hover:border-brand-blue/50 rounded-[2rem] p-6 transition-all duration-500 hover:-translate-y-1">
                                    <h3 className="text-xl font-bold mb-2 group-hover:text-brand-blue transition-colors">{session.title}</h3>
                                    <div className="flex items-center gap-2 text-slate-400 text-sm mb-6">
                                        <Icon name="User" size={14} />
                                        <span>Hosted by {session.host?.full_name || 'Instructor'}</span>
                                    </div>
                                    <Button 
                                        fullWidth 
                                        variant="secondary" 
                                        size="sm"
                                        onClick={() => {
                                            if (!user) {
                                                addToast('Please login to join the brainstorm room', 'info');
                                                navigate('/login');
                                                return;
                                            }
                                            navigate(`/academy/live/${session.meeting_id}`);
                                        }}
                                    >
                                        JOIN ROOM
                                    </Button>
                                </div>
                            )) : (
                                <div className="col-span-full py-20 text-center bg-white/5 rounded-[3rem] border-2 border-dashed border-white/10">
                                    <Icon name="Activity" className="mx-auto text-slate-700 mb-4" size={48} />
                                    <p className="text-slate-500 font-bold uppercase tracking-widest text-xs">No active rooms. Be the pioneer!</p>
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Upcoming Column */}
                    <div>
                        <div className="flex items-center gap-3 mb-6">
                            <Icon name="Calendar" className="text-purple-400" />
                            <h2 className="text-2xl font-black italic tracking-tight">UPCOMING</h2>
                        </div>

                        <div className="space-y-4">
                            {scheduledSessions.length > 0 ? scheduledSessions.map(session => (
                                <div key={session.id} className="group bg-white/5 border border-white/5 rounded-2xl p-5 hover:border-white/10 transition-colors">
                                    <div className="flex justify-between items-start mb-1">
                                        <div className="text-[10px] font-black text-purple-400 uppercase tracking-widest">
                                            {new Date(session.start_time).toLocaleDateString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })}
                                        </div>
                                        {session.host_id === user?.id && (
                                            <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                <button 
                                                    onClick={() => handleEditClick(session)}
                                                    className="p-1 hover:text-brand-blue transition-colors"
                                                    title="Edit Session"
                                                >
                                                    <Icon name="Edit2" size={14} />
                                                </button>
                                                <button 
                                                    onClick={() => handleDeleteSession(session)}
                                                    className="p-1 hover:text-red-500 transition-colors"
                                                    title="Delete Session"
                                                >
                                                    <Icon name="Trash2" size={14} />
                                                </button>
                                            </div>
                                        )}
                                    </div>
                                    <h4 className="font-bold mb-3">{session.title}</h4>
                                    <div className="flex items-center justify-between text-xs">
                                        <span className="text-slate-500 italic">By {session.host?.full_name || 'Guest'}</span>
                                        {session.host_id === user?.id ? (
                                            <button 
                                                onClick={() => handleStartScheduledSession(session)}
                                                className="text-brand-blue font-black uppercase tracking-widest hover:underline flex items-center gap-1 group/btn"
                                            >
                                                <Icon name="Zap" size={12} className="group-hover/btn:animate-pulse" />
                                                Start Session
                                            </button>
                                        ) : (
                                            <button className="text-slate-500 font-bold hover:text-brand-blue transition-colors">SET REMINDER</button>
                                        )}
                                    </div>
                                </div>
                            )) : (
                                <p className="text-slate-600 text-sm italic py-4 text-center">Nothing scheduled yet...</p>
                            )}
                        </div>
                    </div>
                </div>
            </main>

            <Footer />

            {/* Schedule Modal */}
            <Modal 
                isOpen={isScheduleModalOpen} 
                onClose={() => {
                    setIsScheduleModalOpen(false);
                    setEditingSession(null);
                    setScheduleData({ title: '', date: '', time: '' });
                }}
                title={editingSession ? "Edit Brainstorm" : "Schedule Brainstorm"}
            >
                <form onSubmit={handleScheduleSession} className="space-y-6">
                    <div>
                        <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-2">Room Title</label>
                        <input 
                            type="text"
                            required
                            placeholder="e.g. Mastercard Essay Review"
                            className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-brand-blue outline-none transition-colors"
                            value={scheduleData.title}
                            onChange={e => setScheduleData({...scheduleData, title: e.target.value})}
                        />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-2">Date</label>
                            <input 
                                type="date"
                                required
                                className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-brand-blue outline-none transition-colors"
                                value={scheduleData.date}
                                onChange={e => setScheduleData({...scheduleData, date: e.target.value})}
                            />
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-2">Time</label>
                            <input 
                                type="time"
                                required
                                className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-brand-blue outline-none transition-colors"
                                value={scheduleData.time}
                                onChange={e => setScheduleData({...scheduleData, time: e.target.value})}
                            />
                        </div>
                    </div>

                    <div className="border-t border-white/5 pt-6">
                        <div className="flex justify-between items-center mb-4">
                            <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500">Committed Partners ({lobbyMembers.length})</label>
                            {lobbyMembers.length < 2 && (
                                <span className="text-[9px] font-bold text-amber-500 animate-pulse">Minimum 2 required</span>
                            )}
                        </div>
                        
                        {/* Selected Members */}
                        <div className="flex flex-wrap gap-2 mb-4">
                            {lobbyMembers.map(member => (
                                <div key={member.id} className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-brand-blue/10 border border-brand-blue/20">
                                    <div className="w-5 h-5 rounded-full bg-brand-blue/20 flex items-center justify-center overflow-hidden">
                                        <img src={member.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(member.full_name || 'H')}`} className="w-full h-full object-cover" alt="" />
                                    </div>
                                    <span className="text-xs font-bold text-brand-blue">{member.full_name}</span>
                                    {member.id !== user?.id && (
                                        <button type="button" onClick={() => handleRemoveLobbyMember(member.id)} className="text-brand-blue/50 hover:text-brand-blue transition-colors">
                                            <Icon name="X" size={12} />
                                        </button>
                                    )}
                                </div>
                            ))}
                        </div>

                        {/* Member Search */}
                        <div className="relative">
                            <div className="relative">
                                <Icon name="Search" className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" size={14} />
                                <input 
                                    type="text"
                                    placeholder="Search members to invite..."
                                    className="w-full bg-white/5 border border-white/10 rounded-xl pl-9 pr-4 py-2.5 text-sm text-white focus:border-brand-blue outline-none transition-colors"
                                    value={memberSearch}
                                    onChange={e => setMemberSearch(e.target.value)}
                                    onFocus={() => setIsSearchFocused(true)}
                                />
                            </div>

                            {/* Search/Online Results */}
                            {isSearchFocused && (
                                <div className="absolute z-50 w-full mt-2 bg-[#1A1D24] border border-white/10 rounded-xl shadow-2xl overflow-hidden animate-in fade-in slide-in-from-top-2">
                                    {memberSearch.trim().length < 2 ? (
                                        <div>
                                            <div className="px-4 py-2 border-b border-white/5 bg-white/[0.02]">
                                                <p className="text-[9px] font-black uppercase tracking-widest text-slate-500">Suggested Members</p>
                                            </div>
                                            {onlineUsers.length > 0 ? onlineUsers.map(result => (
                                                <button
                                                    key={result.id}
                                                    type="button"
                                                    onClick={() => {
                                                        handleAddLobbyMember(result);
                                                        setIsSearchFocused(false);
                                                    }}
                                                    className="w-full flex items-center gap-3 px-4 py-3 hover:bg-white/5 transition-colors text-left"
                                                >
                                                    <div className="relative">
                                                        <img src={result.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(result.full_name || 'H')}`} className="w-8 h-8 rounded-lg border border-white/10" alt="" />
                                                        <div className="absolute -bottom-0.5 -right-0.5 w-2.5 h-2.5 bg-green-500 border-2 border-[#1A1D24] rounded-full" />
                                                    </div>
                                                    <div>
                                                        <p className="text-sm font-bold">{result.full_name}</p>
                                                        <p className="text-[10px] text-slate-500 uppercase font-black">{result.role || 'Member'}</p>
                                                    </div>
                                                </button>
                                            )) : (
                                                <p className="px-4 py-6 text-center text-xs text-slate-500 italic">No other members active right now.</p>
                                            )}
                                        </div>
                                    ) : (
                                        <div>
                                            <div className="px-4 py-2 border-b border-white/5 bg-white/[0.02]">
                                                <p className="text-[9px] font-black uppercase tracking-widest text-slate-500">Search Results</p>
                                            </div>
                                            {searchResults.length > 0 ? searchResults.map(result => (
                                                <button
                                                    key={result.id}
                                                    type="button"
                                                    onClick={() => {
                                                        handleAddLobbyMember(result);
                                                        setIsSearchFocused(false);
                                                    }}
                                                    className="w-full flex items-center gap-3 px-4 py-3 hover:bg-white/5 transition-colors text-left"
                                                >
                                                    <img src={result.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(result.full_name || 'H')}`} className="w-8 h-8 rounded-lg border border-white/10" alt="" />
                                                    <div>
                                                        <p className="text-sm font-bold">{result.full_name}</p>
                                                        <p className="text-[10px] text-slate-500 uppercase font-black">{result.role || 'Member'}</p>
                                                    </div>
                                                </button>
                                            )) : (
                                                <p className="px-4 py-6 text-center text-xs text-slate-500 italic">No members found for "{memberSearch}"</p>
                                            )}
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    </div>

                    <div className="pt-4">
                        <Button type="submit" fullWidth disabled={isCreating || lobbyMembers.length < 2}>
                            {isCreating ? (editingSession ? 'SAVING...' : 'SCHEDULING...') : (editingSession ? 'SAVE CHANGES' : 'CONFIRM SCHEDULE')}
                        </Button>
                        {lobbyMembers.length < 2 && (
                            <p className="text-center text-[10px] text-slate-500 mt-4 italic">
                                * Add at least one partner to schedule this brainstorm.
                            </p>
                        )}
                    </div>
                </form>
            </Modal>

            <Modal 
                isOpen={isStartNowModalOpen} 
                onClose={() => setIsStartNowModalOpen(false)}
                title="Prepare Brainstorm Lobby"
            >
                <div className="space-y-6">
                    <div>
                        <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500 mb-2">Topic or Goal</label>
                        <input 
                            type="text"
                            required
                            placeholder="What are we brainstorming today?"
                            className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-white focus:border-brand-blue outline-none transition-colors"
                            value={startNowTitle}
                            onChange={e => setStartNowTitle(e.target.value)}
                        />
                    </div>

                    <div>
                        <div className="flex justify-between items-center mb-2">
                            <label className="block text-[10px] font-black uppercase tracking-widest text-slate-500">Lobby Members ({lobbyMembers.length})</label>
                            {lobbyMembers.length < 2 && (
                                <span className="text-[9px] font-bold text-amber-500 animate-pulse">Minimum 2 required</span>
                            )}
                        </div>
                        
                        {/* Selected Members */}
                        <div className="flex flex-wrap gap-2 mb-4">
                            {lobbyMembers.map(member => (
                                <div key={member.id} className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-brand-blue/10 border border-brand-blue/20">
                                    <div className="w-5 h-5 rounded-full bg-brand-blue/20 flex items-center justify-center overflow-hidden">
                                        <img src={member.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(member.full_name || 'H')}`} className="w-full h-full object-cover" alt="" />
                                    </div>
                                    <span className="text-xs font-bold text-brand-blue">{member.full_name}</span>
                                    {member.id !== user?.id && (
                                        <button onClick={() => handleRemoveLobbyMember(member.id)} className="text-brand-blue/50 hover:text-brand-blue transition-colors">
                                            <Icon name="X" size={12} />
                                        </button>
                                    )}
                                </div>
                            ))}
                        </div>

                        {/* Member Search */}
                        <div className="relative">
                            <div className="relative">
                                <Icon name="Search" className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" size={14} />
                                <input 
                                    type="text"
                                    placeholder="Search members to invite..."
                                    className="w-full bg-white/5 border border-white/10 rounded-xl pl-9 pr-4 py-2.5 text-sm text-white focus:border-brand-blue outline-none transition-colors"
                                    value={memberSearch}
                                    onChange={e => setMemberSearch(e.target.value)}
                                    onFocus={() => setIsSearchFocused(true)}
                                />
                            </div>

                            {/* Search/Online Results */}
                            {isSearchFocused && (
                                <div className="absolute z-50 w-full mt-2 bg-[#1A1D24] border border-white/10 rounded-xl shadow-2xl overflow-hidden animate-in fade-in slide-in-from-top-2">
                                    {memberSearch.trim().length < 2 ? (
                                        // Show Online Users
                                        <div>
                                            <div className="px-4 py-2 border-b border-white/5 bg-white/[0.02]">
                                                <p className="text-[9px] font-black uppercase tracking-widest text-slate-500">Suggested Members</p>
                                            </div>
                                            {onlineUsers.length > 0 ? onlineUsers.map(result => (
                                                <button
                                                    key={result.id}
                                                    onClick={() => {
                                                        handleAddLobbyMember(result);
                                                        setIsSearchFocused(false);
                                                    }}
                                                    className="w-full flex items-center gap-3 px-4 py-3 hover:bg-white/5 transition-colors text-left"
                                                >
                                                    <div className="relative">
                                                        <img src={result.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(result.full_name || 'H')}`} className="w-8 h-8 rounded-lg border border-white/10" alt="" />
                                                        <div className="absolute -bottom-0.5 -right-0.5 w-2.5 h-2.5 bg-green-500 border-2 border-[#1A1D24] rounded-full" />
                                                    </div>
                                                    <div>
                                                        <p className="text-sm font-bold">{result.full_name}</p>
                                                        <p className="text-[10px] text-slate-500 uppercase font-black">{result.role || 'Member'}</p>
                                                    </div>
                                                </button>
                                            )) : (
                                                <p className="px-4 py-6 text-center text-xs text-slate-500 italic">No other members active right now.</p>
                                            )}
                                        </div>
                                    ) : (
                                        // Show Search Results
                                        <div>
                                            <div className="px-4 py-2 border-b border-white/5 bg-white/[0.02]">
                                                <p className="text-[9px] font-black uppercase tracking-widest text-slate-500">Search Results</p>
                                            </div>
                                            {searchResults.length > 0 ? searchResults.map(result => (
                                                <button
                                                    key={result.id}
                                                    onClick={() => {
                                                        handleAddLobbyMember(result);
                                                        setIsSearchFocused(false);
                                                    }}
                                                    className="w-full flex items-center gap-3 px-4 py-3 hover:bg-white/5 transition-colors text-left"
                                                >
                                                    <img src={result.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(result.full_name || 'H')}`} className="w-8 h-8 rounded-lg border border-white/10" alt="" />
                                                    <div>
                                                        <p className="text-sm font-bold">{result.full_name}</p>
                                                        <p className="text-[10px] text-slate-500 uppercase font-black">{result.role || 'Member'}</p>
                                                    </div>
                                                </button>
                                            )) : (
                                                <p className="px-4 py-6 text-center text-xs text-slate-500 italic">No members found for "{memberSearch}"</p>
                                            )}
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Click outside to close search */}
                    {isSearchFocused && (
                        <div className="fixed inset-0 z-40" onClick={() => setIsSearchFocused(false)} />
                    )}

                    <div className="pt-4">
                        <Button 
                            fullWidth 
                            disabled={isCreating || lobbyMembers.length < 2 || !startNowTitle} 
                            onClick={confirmCreateNow}
                            iconName={isCreating ? "Loader2" : "Zap"}
                        >
                            {isCreating ? 'CREATING LOBBY...' : 'SEND FOR APPROVAL'}
                        </Button>
                        {lobbyMembers.length < 2 && (
                            <p className="text-center text-[10px] text-slate-500 mt-4 italic">
                                * Add at least one other member to start this brainstorm.
                            </p>
                        )}
                    </div>
                </div>
            </Modal>

            {/* Delete Confirmation Modal */}
            <Modal
                isOpen={!!sessionToDelete}
                onClose={() => setSessionToDelete(null)}
                title="Cancel Brainstorm?"
                size="sm"
            >
                <div className="space-y-6">
                    <div className="p-4 rounded-2xl bg-red-500/10 border border-red-500/20 text-center">
                        <Icon name="AlertTriangle" className="text-red-500 mx-auto mb-3" size={32} />
                        <p className="text-sm text-slate-300">
                            Are you sure you want to cancel <span className="text-white font-bold">"{sessionToDelete?.title}"</span>? This action cannot be undone.
                        </p>
                    </div>
                    
                    <div className="flex gap-3">
                        <Button 
                            variant="secondary" 
                            fullWidth 
                            onClick={() => setSessionToDelete(null)}
                            disabled={isCreating}
                        >
                            KEEP IT
                        </Button>
                        <Button 
                            variant="danger" 
                            fullWidth 
                            onClick={confirmDelete}
                            disabled={isCreating}
                            className="bg-red-600 hover:bg-red-700"
                        >
                            {isCreating ? 'CANCELING...' : 'YES, CANCEL'}
                        </Button>
                    </div>
                </div>
            </Modal>

            <AuthRequiredModal 
                isOpen={isAuthModalOpen} 
                onClose={() => setIsAuthModalOpen(false)} 
                context="host"
            />
        </div>
    );
};

export default BrainstormSessions;
